'use strict';

const FAMILY_ORDER = ['ac','at','au','cm','ia','ir','ma','mp','ps','pe','ra','ca','sc','si'];

const CONTROLS_GUIDE = {

  ac: {
    name: 'Access Control', section: '3.1', count: 22, readTime: '14 min',
    summary: 'The largest family — 22 requirements governing who and what can access your systems, what they can do once in, and how remote, wireless, and mobile access is secured.',
    intro: 'Access Control is NIST SP 800-171\'s largest family and the most frequently cited source of CMMC findings. Its 22 requirements span account authorization, least privilege, CUI flow enforcement, session management, remote access, wireless security, and mobile device controls. Weaknesses here are almost always found by assessors.',
    themes: ['Account Management','Least Privilege','CUI Data Flow','Session Controls','Remote Access','Wireless & Mobile'],
    requirements: [
      { id:'3.1.1', pts:5, title:'Authorized User Access',
        text:'Limit system access to authorized users, processes acting on behalf of authorized users, and devices (including other systems).',
        explanation:'Every person, automated process, and device touching your environment must be explicitly authorized. Maintain an access authorization list for every in-scope system and enforce it technically through Active Directory groups, firewall ACLs, or application-level permissions. "Anyone on the network can reach it" is a direct gap.',
        evidence:['Account inventory or AD group list documenting authorized users per system','Access control policy defining how authorization is granted, reviewed, and revoked','Technical configuration evidence showing access is enforced (firewall ACLs, application role assignments)','Access recertification records showing periodic review']},
      { id:'3.1.2', pts:5, title:'Authorized Transactions and Functions',
        text:'Limit system access to the types of transactions and functions that authorized users are permitted to execute.',
        explanation:'Authorization isn\'t just about who can log in — it\'s about what they can do once they\'re in. Role-based access controls (RBAC) must restrict users to only the functions their role requires. A technician who can approve their own change requests, or a standard user who can install software, are failures of this control.',
        evidence:['RBAC role matrix documenting permissions per role','Application permission configuration screenshots (e.g., SharePoint, application role assignments)','Policy defining role definitions and access tiers','Evidence of periodic access reviews against role definitions']},
      { id:'3.1.3', pts:3, title:'CUI Flow Control',
        text:'Control the flow of CUI in accordance with approved authorizations.',
        explanation:'Document and enforce the approved paths CUI can travel — between systems, to external parties, and to storage locations. Unapproved flows (emailing CUI to personal accounts, syncing to unauthorized cloud storage) must be technically blocked or detected. A CUI data flow diagram and DLP controls are the standard evidence artifacts.',
        evidence:['Data flow diagram documenting all approved CUI flows','DLP policy or email security configuration blocking unapproved CUI destinations','Network segmentation or firewall rules enforcing CUI flow boundaries','Policy defining approved CUI repositories and transmission channels']},
      { id:'3.1.4', pts:3, title:'Separation of Duties',
        text:'Separate the duties of individuals to reduce the risk of malevolent activity without collusion.',
        explanation:'No single person should have unchecked control over high-risk functions. The person who requests a change should not also approve and implement it. The person managing financial disbursements should not control the records of those disbursements. Even small teams can document and enforce this separation.',
        evidence:['Role matrix explicitly showing separation for sensitive functions','Change management system showing distinct requester, approver, and implementer roles','Access control configuration showing audit management separated from system administration','Policy document defining duty separation requirements']},
      { id:'3.1.5', pts:3, title:'Least Privilege',
        text:'Employ the principle of least privilege, including for specific security functions and privileged accounts.',
        explanation:'Every account — human and service — should have only the permissions required for its specific function, and nothing more. Administrators should not hold domain admin rights if they only manage one application. Service accounts should not have local admin rights if they only read a directory. Grant minimum necessary access by default.',
        evidence:['Privileged account inventory with documented justification per privilege level','Service account permission list showing minimum necessary rights','Access review records showing periodic right-sizing of permissions','Policy requiring documented business justification for privileged access']},
      { id:'3.1.6', pts:1, title:'Non-Privileged Account Use',
        text:'Use non-privileged accounts or roles when accessing non-security functions.',
        explanation:'Administrators must use separate, standard user accounts for everyday tasks like email and web browsing. Using an admin account for all activities dramatically expands the attack surface — a single phishing email can lead to full domain compromise. Implement distinct admin and standard accounts for the same individuals.',
        evidence:['Account inventory showing separate privileged and standard accounts for admin personnel','Policy requiring use of standard accounts for non-administrative tasks','User attestation or training records confirming awareness of this requirement','PAM/PIM solution configuration enforcing this separation if applicable']},
      { id:'3.1.7', pts:5, title:'Privileged Function Prevention',
        text:'Prevent non-privileged users from executing privileged functions and capture the execution of such functions in audit logs.',
        explanation:'Standard users must be technically blocked from running privileged operations — installing software, modifying system configurations, escalating privileges. When privileged accounts execute privileged functions, those actions must generate audit log entries. Implemented via UAC on Windows, sudoers/PAM on Linux, or Privileged Access Management solutions.',
        evidence:['Group Policy or MDM configuration showing standard users cannot install software or modify system settings','Audit log samples capturing privileged function execution by admin accounts','Sudo or PAM configuration on Linux/Unix systems','Policy defining privileged function restrictions and logging requirements']},
      { id:'3.1.8', pts:3, title:'Unsuccessful Logon Attempts',
        text:'Limit unsuccessful logon attempts.',
        explanation:'Systems must lock accounts or apply throttling after a defined number of consecutive failed logins to prevent brute-force attacks. Configure lockout in Active Directory and verify that application-layer authentication also enforces it — AD lockout does not automatically protect all application logins.',
        evidence:['Active Directory Group Policy showing account lockout threshold (≤ 10 attempts typical)','Application authentication configuration showing lockout or rate-limiting policy','Identity provider screenshot (Azure AD, Okta) showing lockout settings','Security policy defining threshold and lockout duration']},
      { id:'3.1.9', pts:1, title:'Privacy and Security Notices',
        text:'Provide privacy and security notices consistent with CUI rules (as established by NARA).',
        explanation:'Systems must display a login banner before authentication notifying users of authorized use, monitoring, and applicable CUI handling rules. The banner text must align with NARA CUI requirements. Assessors routinely check this across all systems — servers, workstations, VPNs, and web applications.',
        evidence:['Screenshots of login banners on representative systems (Windows, Linux, VPN portal, web apps)','Banner text compared against NARA CUI advisory guidance','GPO configuration deploying the banner to all Windows systems','SSH banner configuration (/etc/issue.net or /etc/motd) on Linux/Unix servers']},
      { id:'3.1.10', pts:1, title:'Session Lock',
        text:'Use session lock with pattern-hiding displays after a period of inactivity.',
        explanation:'Workstations and servers must automatically lock and obscure the display after a defined inactivity period — not just activate a screensaver. The lock must require re-authentication to dismiss. Configure via Group Policy for Windows, equivalent MDM profiles for macOS, and PAM screensaver settings for Linux.',
        evidence:['Group Policy Object showing screen lock timeout (≤ 15 minutes typical)','macOS MDM profile showing screen lock enforcement','Evidence that re-authentication is required to dismiss the lock','Policy defining the inactivity timeout period']},
      { id:'3.1.11', pts:1, title:'Session Termination',
        text:'Terminate (automatically) a user session after a defined condition.',
        explanation:'Session termination goes beyond screen lock — the actual session must end after a defined condition (typically an idle timeout), requiring full re-authentication to resume. This applies to interactive OS sessions, web application sessions, and VPN sessions. Session lock and session termination are distinct controls; both must be satisfied.',
        evidence:['VPN configuration showing idle session timeout and automatic disconnect','Web application session timeout configuration','GPO settings for interactive session termination on Windows','Policy defining session termination conditions and timeout values']},
      { id:'3.1.12', pts:3, title:'Remote Access Monitoring',
        text:'Monitor and control remote access sessions.',
        explanation:'Remote access sessions must be actively monitored — not just permitted. This means logging all remote access activity, reviewing those logs, and maintaining the ability to terminate a session. VPN connection logs should be retained and reviewed for anomalies, ideally fed into a SIEM.',
        evidence:['VPN or remote access logs showing session details (user, source IP, duration)','SIEM alert configuration for anomalous remote access patterns','Log review procedure showing frequency and scope of review','Evidence of ability to terminate remote sessions (admin console or kill command)']},
      { id:'3.1.13', pts:5, title:'Remote Access Encryption',
        text:'Employ cryptographic mechanisms to protect the confidentiality of remote access sessions.',
        explanation:'Remote access connections must use approved encryption — TLS 1.2+, or FIPS-validated VPN protocols. Unencrypted remote access (Telnet, RDP over public internet without a VPN, HTTP-based admin interfaces accessible externally) is a critical finding. Verify cipher suites and protocol versions, not just that encryption is "on."',
        evidence:['VPN configuration showing encryption algorithm (AES-256) and protocol (IKEv2, TLS 1.2+)','SSL/TLS scan results for remote access portals confirming strong cipher suites and no weak protocols','Remote desktop gateway or Citrix configuration showing encryption settings','Policy requiring encryption for all remote access with approved cipher requirements']},
      { id:'3.1.14', pts:3, title:'Managed Remote Access Points',
        text:'Route remote access via managed access control points.',
        explanation:'All remote access must funnel through organization-controlled gateways — VPN concentrators, bastion hosts, or jump servers. Users cannot make direct connections to internal resources without traversing an organizational access control point. This prevents attackers from establishing channels that bypass perimeter controls.',
        evidence:['Network diagram showing all remote access routing through managed gateways','Firewall rules blocking direct inbound connections to internal systems','VPN gateway or bastion host configuration documentation','Policy prohibiting direct remote access to endpoints that bypasses a managed gateway']},
      { id:'3.1.15', pts:3, title:'Remote Privileged Command Authorization',
        text:'Authorize remote execution of privileged commands via remote access only for documented operational needs.',
        explanation:'Running privileged commands remotely (remote PowerShell, SSH to production servers) must be explicitly authorized with a documented business justification. Ad-hoc remote admin activity with no documented need is a finding. Maintain a list of authorized remote privileged access scenarios.',
        evidence:['Policy listing authorized remote privileged command scenarios with documented justification','Change management records authorizing specific remote admin activities','PAM system logs showing authorization before privileged remote access','Access request and approval records for remote privileged access capabilities']},
      { id:'3.1.16', pts:1, title:'Wireless Access Authorization',
        text:'Authorize wireless access prior to allowing such connections.',
        explanation:'All wireless access points and connections must be formally authorized before being allowed on the network. Maintain an inventory of authorized wireless infrastructure and a process for requesting and approving wireless access. Rogue access points must be detectable.',
        evidence:['Wireless access point inventory with authorization records','Wireless access policy defining authorization requirements','MDM or NAC configuration rejecting unauthorized devices','Wireless scanning or WIDS capability to detect rogue access points']},
      { id:'3.1.17', pts:3, title:'Wireless Authentication and Encryption',
        text:'Protect wireless access using authentication and encryption.',
        explanation:'Wireless networks providing access to CUI must use enterprise-grade authentication (WPA2-Enterprise or WPA3-Enterprise with 802.1X) and strong encryption (AES-CCMP). WPA2-PSK (shared password) is insufficient for CUI environments. Guest networks must be completely isolated from CUI systems.',
        evidence:['Wireless controller configuration showing WPA2/WPA3-Enterprise with 802.1X','RADIUS server configuration for wireless 802.1X authentication','Network diagram showing CUI network segregation from guest and personal wireless','Policy prohibiting WEP, TKIP, and shared-key authentication for CUI-connected wireless']},
      { id:'3.1.18', pts:1, title:'Mobile Device Connection Control',
        text:'Control connection of mobile devices.',
        explanation:'The organization must control which mobile devices can connect to organizational systems and under what conditions. An MDM solution with device enrollment requirements and a configuration baseline is the standard implementation. Unenrolled or personal devices accessing CUI without policy controls are a finding.',
        evidence:['MDM enrollment and configuration policy','MDM solution dashboard showing enrolled devices and compliance status','Conditional access policy requiring MDM enrollment for CUI access','Acceptable use policy governing personal mobile device use for CUI work']},
      { id:'3.1.19', pts:5, title:'CUI Encryption on Mobile Devices',
        text:'Encrypt CUI on mobile devices and mobile computing platforms.',
        explanation:'CUI stored on or accessible from mobile devices — smartphones, tablets, and laptops — must be protected with full-device encryption using FIPS-validated mechanisms. BitLocker (Windows), FileVault (macOS), and Android/iOS native encryption all qualify. BYOD devices accessing CUI are subject to the same requirement.',
        evidence:['MDM compliance report showing encryption enforcement on all enrolled devices','BitLocker Group Policy configuration showing FIPS-mode encryption','FileVault MDM profile showing macOS encryption enforcement','Policy requiring device-level encryption for all devices accessing or storing CUI']},
      { id:'3.1.20', pts:1, title:'External System Connections',
        text:'Verify and control/limit connections to external information systems.',
        explanation:'Connections to external systems — cloud services, partner networks, SaaS platforms — must be inventoried, verified as authorized, and controlled. You must know what external connections exist and apply appropriate controls. An unmanaged cloud sync that can receive CUI is a gap here.',
        evidence:['External connection inventory documenting all approved connections','Interconnection Security Agreements (ISAs) for significant external connections','Firewall egress rules controlling outbound connections to external systems','Policy defining the authorization process for new external connections']},
      { id:'3.1.21', pts:3, title:'Portable Storage on External Systems',
        text:'Limit use of portable storage devices on external information systems.',
        explanation:'When organization-owned portable storage is used on external or non-organization-controlled systems, that use must be controlled or prohibited. The risk is CUI on a portable drive being connected to an uncontrolled system where it could be accessed or exposed. Technical controls are more reliable than policy alone.',
        evidence:['Policy limiting or prohibiting use of organization-issued portable storage on external systems','Endpoint management configuration blocking USB use on non-organization-managed systems','Training records covering portable storage handling requirements','DLP configuration alerting on CUI written to portable storage']},
      { id:'3.1.22', pts:5, title:'CUI on Publicly Accessible Systems',
        text:'Control CUI posted or processed on publicly accessible information systems.',
        explanation:'If CUI must be posted to or processed by a publicly accessible system (a public web portal, a public-facing API), strict controls must prevent unauthorized CUI from becoming accessible. Most organizations should simply avoid placing CUI on public systems. If unavoidable, implement review-before-publish workflows and automated CUI detection scanning.',
        evidence:['Policy prohibiting unauthorized CUI on publicly accessible systems','Review and approval workflow for content published to public-facing systems','Regular audit of public-facing systems for inadvertent CUI exposure','Data classification or DLP tool configured to detect CUI before public posting']}
    ],
    findings: [
      'Shared accounts or generic service accounts used by multiple individuals, eliminating individual accountability',
      'Privileged accounts used for routine work (email, web browsing), violating the non-privileged account requirement',
      'Remote access lacking MFA, or MFA configured but not enforced for all users and devices',
      'VPN configured with split tunneling enabled, allowing direct internet traffic to bypass organizational controls',
      'No documented CUI data flow diagrams; CUI flows to unauthorized destinations without technical controls',
      'Session lock timeout exceeding 15 minutes or not requiring re-authentication to unlock',
      'Mobile devices accessing CUI without MDM enrollment, policy, or verified encryption'
    ]
  },

  at: {
    name: 'Awareness and Training', section: '3.2', count: 3, readTime: '5 min',
    summary: 'Three requirements establishing that all personnel understand the security risks of their activities and are trained to fulfill their security responsibilities.',
    intro: 'The Awareness and Training family has only 3 requirements, but two of them carry maximum 5-point weight. The core obligation is ensuring that everyone who touches your systems — from end users to system administrators — has been trained on the security risks of their activities, their responsibilities, and how to recognize and report threats.',
    themes: ['Security Awareness','Role-Based Training','Threat Recognition','Social Engineering'],
    requirements: [
      { id:'3.2.1', pts:5, title:'Security Risk Awareness',
        text:'Ensure that managers, systems administrators, and users of organizational systems are made aware of the security risks associated with their activities and of applicable policies, standards, and procedures.',
        explanation:'All personnel with system access — not just IT staff — must receive security awareness training that covers the specific risks associated with their roles and the applicable organizational policies. A one-time onboarding module is insufficient; training must be ongoing and documented. The content must be role-aware, not entirely generic.',
        evidence:['Training records showing all personnel (managers, admins, users) completed awareness training annually','Training content covering applicable policies, CUI handling requirements, and job-specific risks','Training completion tracking tied to user accounts or HR records','Evidence of follow-up for personnel who did not complete training']},
      { id:'3.2.2', pts:5, title:'Role-Based Security Training',
        text:'Ensure that organizational personnel are adequately trained to carry out their assigned information security-related responsibilities.',
        explanation:'Personnel with specific security duties — system administrators, the ISSO, incident responders, change managers — must receive training specific to those responsibilities. General awareness training does not satisfy this for technical staff. A sysadmin who hasn\'t been trained on secure configuration and hardening is a gap.',
        evidence:['Role-specific training curriculum tied to security responsibilities (admin hardening, IR procedures)','Training completion records organized by role','Job descriptions identifying security responsibilities that training must address','Evidence of training when personnel assume new security-relevant roles']},
      { id:'3.2.3', pts:3, title:'Threat and Social Engineering Awareness',
        text:'Provide security awareness training on recognizing and reporting potential threats including social engineering attacks.',
        explanation:'All personnel must be trained to identify and report social engineering attacks — phishing, vishing, pretexting, baiting, and tailgating. Training must also establish a clear reporting path so personnel know what to do when they encounter a suspected attack. Simulated phishing campaigns are a common and effective evidence artifact.',
        evidence:['Security awareness training content covering phishing, vishing, and social engineering tactics','Simulated phishing campaign results showing test frequency and click rates','Incident reporting procedure prominently communicated to all personnel','Records showing personnel know how and where to report suspected threats']}
    ],
    findings: [
      'Training records are incomplete — not all personnel have documented completion on file',
      'Training content is entirely generic and does not address CUI-specific handling requirements',
      'Role-based training for system administrators covers only general awareness rather than technical security responsibilities',
      'No simulated phishing or social engineering exercises conducted; threat awareness is policy-only'
    ]
  },

  au: {
    name: 'Audit and Accountability', section: '3.3', count: 9, readTime: '8 min',
    summary: 'Nine requirements governing what events must be logged, how logs are protected and reviewed, and how individual users are held accountable for their actions.',
    intro: 'Audit and Accountability establishes the evidentiary foundation for security monitoring, incident investigation, and user accountability. Its 9 requirements cover log generation and retention, individual user traceability, log protection, alerting on logging failures, and correlation of audit data. A system without adequate logging is both a compliance gap and a significant operational blind spot.',
    themes: ['Log Generation','User Accountability','Log Retention','Log Protection','Time Synchronization','Alerting'],
    requirements: [
      { id:'3.3.1', pts:3, title:'Audit Log Creation and Retention',
        text:'Create and retain system audit logs and records to the extent needed to enable the monitoring, analysis, investigation, and reporting of unlawful or unauthorized system activity.',
        explanation:'Systems must generate audit logs capturing security-relevant events and retain them long enough to support investigations. Define your retention period in policy — 90 days of online retention with 1 year total is a common baseline. Log coverage must include authentication events, privilege use, account changes, and CUI access where possible.',
        evidence:['Log configuration screenshots showing what events are captured on representative systems','Log retention policy defining minimum retention period','Log storage configuration showing current retention capacity and period','Sample log exports demonstrating captured event types']},
      { id:'3.3.2', pts:3, title:'User Accountability',
        text:'Ensure that the actions of individual system users can be traced to those users so they can be held accountable for their actions.',
        explanation:'Every action in the audit log must be attributable to a specific individual — not to a shared service account or "the system." Shared accounts fundamentally undermine this requirement. Each person must have a unique account ID, and service accounts must have designated individual owners.',
        evidence:['Audit log sample showing user identity tied to individual actions (not shared accounts)','Policy prohibiting shared accounts and requiring unique identifiers per user','Service account inventory with designated individual owners','Evidence that shared accounts have been eliminated or documented exceptions justified']},
      { id:'3.3.3', pts:1, title:'Logged Event Review',
        text:'Review and update logged events.',
        explanation:'The list of audited events must be reviewed periodically to ensure it remains appropriate as systems and threats evolve. What was sufficient to log two years ago may not cover current risks. Document what events you log, why, and when you last reviewed the list.',
        evidence:['Logged event list with last-reviewed date documented','Policy defining review frequency (annually at minimum)','Change history showing the event list has been updated when systems changed','Evidence of review tied to system changes or security incidents']},
      { id:'3.3.4', pts:3, title:'Audit Logging Failure Alerts',
        text:'Alert in the event of an audit logging process failure.',
        explanation:'When the logging system itself fails — log storage full, logging service crashes, SIEM connectivity lost — the organization must be immediately alerted. Silent audit failures are a serious risk: you may believe you\'re monitoring when you\'re actually blind. Configure alerts in your SIEM or monitoring platform for logging failures.',
        evidence:['SIEM or monitoring tool alert configuration for log ingestion failures','Alert notification policy defining who receives logging failure alerts and response time','Evidence of a test or recent alert proving the alerting mechanism works','Runbook or procedure for responding to logging failure alerts']},
      { id:'3.3.5', pts:3, title:'Audit Log Correlation',
        text:'Correlate audit record review, analysis, and reporting processes for investigation and response to indications of unlawful, unauthorized, suspicious, or unusual activity.',
        explanation:'Audit logs from different systems must be reviewed together to detect patterns not visible from any single source. A failed VPN login followed by a successful login from the same IP, then a large file download, is only suspicious when correlated. A SIEM is the standard implementation, but even structured multi-source log review processes can satisfy this.',
        evidence:['SIEM configuration showing log ingestion from multiple sources with correlation rules','Documented log review process referencing multi-source analysis','Investigation procedure showing cross-system log correlation steps','Evidence of correlation detections or investigations in the log review history']},
      { id:'3.3.6', pts:1, title:'Audit Record Reduction and Reporting',
        text:'Provide audit record reduction and report generation to support on-demand analysis and reporting.',
        explanation:'The system must support querying, filtering, and reporting on audit logs on demand — both for routine review and incident investigation. This does not require a full SIEM; cloud-native log tools, Graylog, or even well-structured log archives with search capability can satisfy this.',
        evidence:['Demonstration or screenshot of log query and filter capability','Sample on-demand audit report generated from the system','Log management tool configuration showing search and reporting features','Evidence that investigators can generate reports from log data without manual extraction']},
      { id:'3.3.7', pts:1, title:'Clock Synchronization',
        text:'Provide a system capability that compares and synchronizes internal system clocks with an authoritative source to generate time stamps for audit records.',
        explanation:'All systems must synchronize their clocks to an authoritative NTP source. Without synchronized clocks, correlating logs across systems during an investigation becomes unreliable — a 5-minute discrepancy can make it impossible to reconstruct the sequence of events. Windows AD time sync and NTP daemon configuration are the standard implementations.',
        evidence:['NTP configuration on servers and endpoints (Group Policy for Windows, ntp.conf for Linux)','Authoritative time source configured (e.g., time.nist.gov, pool.ntp.org)','Evidence of clock sync across representative systems','Policy requiring all systems to use the designated time source']},
      { id:'3.3.8', pts:3, title:'Audit Log Protection',
        text:'Protect audit information and audit tools from unauthorized access, modification, and deletion.',
        explanation:'Audit logs must be protected from tampering — an attacker who can delete logs can eliminate evidence of their activity. Use centralized log management with restricted write access, write-once storage, or log forwarding to a system where the originating system\'s admin cannot modify or delete the logs.',
        evidence:['Log storage access controls showing who can read vs. modify or delete logs','Centralized log management configuration with restricted admin access','Write-once or WORM storage configuration for audit logs if applicable','Separation of duties documentation between system admins and log administrators']},
      { id:'3.3.9', pts:1, title:'Privileged Audit Management',
        text:'Limit management of audit logging to a subset of privileged users.',
        explanation:'The ability to configure what gets logged, enable or disable logging, and manage the logging infrastructure must be restricted to a small, defined set of authorized administrators. General system administrators should not have the ability to turn off or modify audit logging on systems they administer.',
        evidence:['Role or permission configuration restricting audit management to designated administrators','Policy defining who is authorized to manage audit logging','Access control list for log management functions','Evidence that general admins cannot disable or modify logging on systems they manage']}
    ],
    findings: [
      'Log retention period too short to support realistic investigations (under 90 days of accessible logs)',
      'Shared accounts in use, making it impossible to attribute log entries to specific individuals',
      'No alerting configured for logging failures — outages go undetected',
      'System clocks not synchronized; significant time discrepancies between systems',
      'Audit log storage accessible to the same administrators who manage the systems being audited'
    ]
  },

  cm: {
    name: 'Configuration Management', section: '3.4', count: 9, readTime: '8 min',
    summary: 'Nine requirements covering baseline configurations, change control, security hardening, and restricting software execution to only what is necessary and authorized.',
    intro: 'Configuration Management controls prevent unauthorized changes, reduce attack surface, and ensure systems remain in a known-good state. Its 9 requirements address baseline configuration maintenance, security hardening, formal change control, pre-change security analysis, and software execution policy. Configuration drift — systems deviating from their approved baselines — is one of the most common CMMC findings.',
    themes: ['Baseline Configurations','Security Hardening','Change Control','Least Functionality','Software Execution Policy'],
    requirements: [
      { id:'3.4.1', pts:3, title:'Baseline Configuration and Inventory',
        text:'Establish and maintain baseline configurations and inventories of organizational systems (including hardware, software, firmware, and documentation) throughout the respective system development life cycles.',
        explanation:'Maintain a documented baseline configuration for every in-scope system — the approved state it should be in when properly configured — along with an inventory of all hardware, software, and firmware. Any deviation from the baseline should trigger change management. You cannot manage what you have not inventoried.',
        evidence:['Hardware and software inventory (asset management tool, CMDB, or spreadsheet)','Baseline configuration documents or configuration management tool exports (Ansible, SCCM, DSC)','Version tracking records for firmware and software','Evidence that inventory is maintained across system lifecycle changes']},
      { id:'3.4.2', pts:3, title:'Security Configuration Settings',
        text:'Establish and enforce security configuration settings for information technology products employed in organizational systems.',
        explanation:'Baseline configurations must include security hardening settings — not just functional settings. Use CIS Benchmarks or DISA STIGs as the basis. Deviations from the benchmark must be formally documented, approved, and justified. "We couldn\'t harden it because the application required it" is only acceptable with documentation.',
        evidence:['Security configuration baselines referencing <a href="https://www.cisecurity.org/cis-benchmarks/" target="_blank" rel="noopener noreferrer">CIS Benchmarks</a> or <a href="https://public.cyber.mil/stigs/" target="_blank" rel="noopener noreferrer">DISA STIGs</a>','Automated compliance scan results (CIS-CAT, SCAP tool, or equivalent)','Deviation documentation for approved exceptions to hardening standards','Policy mandating hardened configurations and the process for approved deviations']},
      { id:'3.4.3', pts:3, title:'Change Control',
        text:'Track, review, approve/disapprove, and log changes to organizational systems.',
        explanation:'All changes to in-scope systems must follow a formal change management process: changes are tracked in a system, reviewed, approved before implementation, and logged. Unauthorized changes — even well-intentioned ones — are a direct finding. The process does not need to be elaborate; even a simple ticketing workflow with approval satisfies this for small shops.',
        evidence:['Change management policy defining the process','Change log or ticketing system records showing recent changes with approvals','Approval workflow documentation showing pre-implementation authorization','Evidence that recent system changes followed the documented process']},
      { id:'3.4.4', pts:3, title:'Security Impact Analysis',
        text:'Analyze the security impact of changes prior to implementation.',
        explanation:'Before implementing any change, a security impact analysis must be completed and documented. This doesn\'t require an elaborate process — a structured field in your change ticket asking "what are the security implications of this change?" satisfies the requirement. The analysis must occur before the change, not after.',
        evidence:['Change management records showing a security impact analysis field for each change','Completed security review checklist for recent changes','Policy requiring pre-change security analysis','Evidence that security findings from the analysis were addressed before the change was approved']},
      { id:'3.4.5', pts:3, title:'Access Restrictions for Changes',
        text:'Define, document, approve, and enforce physical and logical access restrictions associated with changes to organizational systems.',
        explanation:'Not everyone should be able to make production changes. Define who can initiate, approve, and implement changes — and enforce those boundaries technically. This covers both physical access (who can physically access production servers) and logical access (who holds admin credentials to production systems).',
        evidence:['Change management policy defining authorization levels for change initiation, approval, and implementation','Access control configuration limiting who has admin credentials to production systems','Physical access controls to production server rooms and network equipment','Role matrix showing change-related responsibilities and access levels']},
      { id:'3.4.6', pts:3, title:'Least Functionality',
        text:'Employ the principle of least functionality by configuring organizational systems to provide only essential capabilities.',
        explanation:'Systems should be configured to provide only the capabilities required for their defined purpose — nothing more. Every unused feature, service, or installed application is unnecessary attack surface. Disable or remove capabilities the organization does not use, using the baseline configuration as the authoritative list of required functionality.',
        evidence:['Baseline configuration showing disabled services and removed unnecessary features','System hardening records and CIS Benchmark compliance reports','Automated scan results showing unnecessary services are disabled','Policy defining the process for approving and documenting required functionality']},
      { id:'3.4.7', pts:3, title:'Nonessential Programs and Services',
        text:'Restrict, disable, or prevent the use of nonessential programs, functions, ports, protocols, and services.',
        explanation:'Specifically enumerate and disable nonessential programs, ports, protocols, and services. Firewall rules should block unused ports. Legacy protocols like Telnet, FTP, and SMBv1 should be disabled unless specifically required and documented. This is a more specific application of least functionality.',
        evidence:['Firewall rule configuration showing blocked or unused ports','Service configuration screenshots showing disabled nonessential services','Port scan results confirming blocked ports','Policy listing prohibited protocols and the process for approved exceptions']},
      { id:'3.4.8', pts:3, title:'Application Execution Policy',
        text:'Apply deny-by-exception (blacklisting) policy to prevent the use of unauthorized software or deny-all, permit-by-exception (whitelisting) policy to allow the execution of authorized software.',
        explanation:'Implement either a blocklist or — preferably — an allowlist for software execution. Allowlisting (deny all, permit by exception) is significantly more secure and is what assessors expect to see in higher-risk environments. Windows Defender Application Control (WDAC) and AppLocker are the primary Windows implementations.',
        evidence:['Application allowlist or blocklist configuration (WDAC, AppLocker, or equivalent)','Policy documenting the software execution approach (allowlist vs. blocklist) and rationale','Authorized software inventory used as the basis for the allowlist','Evidence of enforcement on representative systems']},
      { id:'3.4.9', pts:1, title:'User-Installed Software',
        text:'Control and monitor user-installed software.',
        explanation:'Users must be prevented from installing software without authorization, or that installation must be controlled and monitored. This prevents shadow IT and unauthorized tools that may introduce vulnerabilities. Endpoint management tools or Group Policy can restrict software installation rights for standard users.',
        evidence:['Policy prohibiting unauthorized software installation','Group Policy or MDM restricting software installation rights for standard user accounts','Software inventory audit process showing detection of unauthorized software','Endpoint protection alerts for unauthorized software installation attempts']}
    ],
    findings: [
      'No formal change management process; changes made ad-hoc without documentation or approval',
      'No security impact analysis step in the change process, or analysis performed after the change',
      'Nonessential services (Telnet, FTP, SMBv1, legacy RPC) still enabled on production systems',
      'Configuration baseline exists as a document but systems are not regularly verified against it',
      'Standard users can install software; no technical enforcement of installation restrictions'
    ]
  },

  ia: {
    name: 'Identification and Authentication', section: '3.5', count: 11, readTime: '9 min',
    summary: 'Eleven requirements covering unique user and device identification, multi-factor authentication, password management, and credential storage and transmission.',
    intro: 'Identification and Authentication establishes the foundation for knowing who is accessing your systems and verifying that they are who they claim to be. Its 11 requirements address unique identifiers, multi-factor authentication, password policies, account lifecycle management, and cryptographic protection of credentials. MFA (3.5.3) is the highest-profile and most frequently cited requirement in this family.',
    themes: ['Unique Identification','Multi-Factor Authentication','Password Policy','Account Lifecycle','Credential Protection'],
    requirements: [
      { id:'3.5.1', pts:5, title:'User and Device Identification',
        text:'Identify information system users, processes acting on behalf of users, and devices.',
        explanation:'Every user, automated process, and device that accesses the system must have a unique identifier. Anonymous access, shared accounts, and generic service accounts used by multiple individuals all fail this requirement. Each identity must be traceable to a specific individual or a defined function with an assigned owner.',
        evidence:['User account inventory showing unique identifiers per individual','Policy requiring unique accounts and prohibiting shared logins','Service account inventory with designated individual owners for each account','Evidence that generic or shared accounts have been eliminated or restricted']},
      { id:'3.5.2', pts:5, title:'Authentication',
        text:'Authenticate (or verify) the identities of users, processes, or devices, as a prerequisite to allowing access to organizational systems.',
        explanation:'Identification alone is insufficient — users and devices must verify their identity before accessing systems. Every access path to CUI systems must require authentication. Unauthenticated access to any system in scope is a critical finding.',
        evidence:['Authentication policy requiring verification before system access','System configuration screenshots confirming all login paths require authentication','Evidence that no system in scope permits unauthenticated access','Network access control or zero-trust policy enforcing authentication at all access points']},
      { id:'3.5.3', pts:5, title:'Multi-Factor Authentication',
        text:'Use multifactor authentication for local and network access to privileged accounts and for network access to non-privileged accounts.',
        explanation:'MFA is required in two scenarios: (1) all access — local or remote — to privileged accounts, and (2) all network (remote) access to any account, privileged or not. Put simply: privileged accounts need MFA everywhere; non-privileged users need MFA when logging in over the network. Password-only access to any of these scenarios is a direct finding.',
        evidence:['MFA configuration in identity provider (Azure AD, Okta, Duo) showing enforcement policies','Conditional access policy requiring MFA for remote access by all users','Evidence that privileged accounts require MFA even for local/console access','MFA enrollment records showing all applicable accounts are enrolled']},
      { id:'3.5.4', pts:1, title:'Replay-Resistant Authentication',
        text:'Employ replay-resistant authentication mechanisms for network access to privileged and non-privileged accounts.',
        explanation:'Authentication mechanisms must resist replay attacks, where a captured authentication token is reused to impersonate a user. Modern protocols — Kerberos, OAuth 2.0, SAML with short-lived tokens, FIDO2 — are inherently replay-resistant. Legacy protocols like NTLMv1 and plain Basic Auth over the network are not.',
        evidence:['Authentication protocol configuration confirming use of modern, replay-resistant protocols','Policy prohibiting NTLMv1, basic authentication over the network, and other deprecated protocols','Network traffic analysis confirming no legacy authentication protocols in use','Identity provider settings showing token lifetimes and replay prevention mechanisms']},
      { id:'3.5.5', pts:1, title:'Identifier Management',
        text:'Manage information system identifiers for users and devices.',
        explanation:'User and device identifiers must be managed across their full lifecycle — provisioned when needed, maintained accurately, and disabled or removed when no longer needed. This requires a formal account provisioning and deprovisioning process tied to HR workflows.',
        evidence:['Account provisioning and deprovisioning procedure','HR-to-IT offboarding workflow showing how departures trigger account disabling','Account creation records showing proper authorization process','Periodic account review results showing active accounts match current personnel']},
      { id:'3.5.6', pts:1, title:'Identifier Inactivity Disabling',
        text:'Disable identifiers after a defined inactivity period.',
        explanation:'Accounts that haven\'t been used for a defined period must be automatically disabled. 90 days is a common threshold. Dormant accounts — forgotten service accounts, former employees\' accounts never properly disabled — are common attack vectors. Automate this with identity management tools or scheduled reviews.',
        evidence:['Account inactivity policy defining the threshold (e.g., 90 days)','Automated account review configuration or script disabling inactive accounts','Recent account audit results showing inactive accounts were disabled','Identity management tool configuration enforcing automatic disabling']},
      { id:'3.5.7', pts:3, title:'Password Complexity',
        text:'Enforce a minimum password complexity and change of characters when new passwords are created.',
        explanation:'Password policies must enforce minimum standards — typically 12 or more characters, with a mix of character types, and rejection of common or previously breached passwords. <a href="https://pages.nist.gov/800-63-3/sp800-63b.html" target="_blank" rel="noopener noreferrer">NIST SP 800-63B</a> guidance emphasizes length over complexity rules, but complexity requirements remain mandatory under 800-171. Configure enforcement in your identity provider, not just in policy.',
        evidence:['Password policy configuration in Group Policy, Azure AD, or identity provider showing complexity rules','Policy document defining minimum password requirements','Screenshot of password creation screen showing enforcement (rejected weak passwords)','Evidence that third-party applications also enforce password complexity where applicable']},
      { id:'3.5.8', pts:1, title:'Password Reuse Prevention',
        text:'Prohibit password reuse for a specified number of generations.',
        explanation:'Users must be prevented from immediately reusing recent passwords when they change credentials. Configure your identity system to remember and reject the last N passwords (24 is a common value). This prevents the pattern of cycling through a small set of passwords to satisfy change requirements.',
        evidence:['Password history configuration in Group Policy or identity provider (showing history count)','Policy defining the number of previous passwords that cannot be reused','Identity provider screenshot confirming enforcement','Evidence that applications with their own authentication also enforce history requirements']},
      { id:'3.5.9', pts:1, title:'Temporary Password Change',
        text:'Allow temporary password use for system logons with an immediate change to a permanent password.',
        explanation:'Initial or temporary passwords — set by IT at account creation or reset — must require immediate change at first login. Systems must technically enforce this, not just request it. This prevents stale initial credentials from remaining valid if the onboarding email is intercepted or delayed.',
        evidence:['System configuration showing "must change password at next logon" enforcement','Account provisioning procedure including the mandatory change requirement','Screenshot showing the forced change prompt at first login','Evidence that this applies to all methods of account creation and password reset']},
      { id:'3.5.10', pts:3, title:'Password Cryptographic Protection',
        text:'Store and transmit only cryptographically-protected passwords.',
        explanation:'Passwords must never be stored in plaintext and must only be transmitted over encrypted channels. Storage must use modern, salted hashing (bcrypt, Argon2, PBKDF2 — not MD5 or SHA1 alone). Transmission must use TLS. This also means no passwords in configuration files, scripts, environment variables in plain text, or emails.',
        evidence:['Application/system documentation confirming password hashing algorithm used','TLS configuration ensuring passwords are never transmitted in cleartext','Code review or security assessment confirming no plaintext password storage in applications','Secrets management solution in use (Vault, AWS Secrets Manager) to prevent passwords in config files']},
      { id:'3.5.11', pts:1, title:'Authentication Feedback Obscuring',
        text:'Obscure feedback of authentication information.',
        explanation:'When a user types a password or enters authentication credentials, the input must be obscured — shown as dots or asterisks, not as readable characters. This prevents shoulder surfing. Standard OS and browser implementations handle this automatically; the risk lies in custom or legacy applications that may display passwords in cleartext.',
        evidence:['Demonstration on representative systems showing obscured password input','Screenshots of authentication screens confirming password masking','Review of any custom-built authentication interfaces for compliance','Policy requiring obscured feedback in application development standards']}
    ],
    findings: [
      'MFA not enforced for remote access, or enforced only for admins but not all non-privileged users accessing the network',
      'Inactive accounts not disabled — former employees\' accounts or orphaned service accounts remain active',
      'Passwords stored using weak or deprecated hashing algorithms (MD5, SHA1, unsalted)',
      'Temporary or initial passwords set by IT do not require immediate change at first login',
      'Shared credentials in use for service accounts, eliminating individual accountability'
    ]
  },

  ir: {
    name: 'Incident Response', section: '3.6', count: 3, readTime: '5 min',
    summary: 'Three requirements establishing an operational incident-handling capability, documenting and reporting incidents to appropriate authorities, and regularly testing the IR capability.',
    intro: 'The Incident Response family has only 3 requirements, but each carries a 3-point weight and together they establish a non-negotiable baseline: you must have a functioning, tested IR capability. The requirements span preparation through reporting, including the specific obligation to report CUI incidents to the DoD via DIBNET within 72 hours.',
    themes: ['IR Planning','Incident Tracking','Reporting to Authorities','IR Testing','DIBNET Reporting'],
    requirements: [
      { id:'3.6.1', pts:3, title:'Incident Handling Capability',
        text:'Establish an operational incident-handling capability for organizational systems that includes preparation, detection, analysis, containment, recovery, and user response activities.',
        explanation:'The organization must have a working, documented, and exercised incident response capability covering all phases: preparation, detection, analysis, containment, eradication, recovery, and post-incident review. A plan that exists only as a document and has never been exercised does not satisfy "operational." IR must be practiced.',
        evidence:['Incident response plan document covering all phases','Evidence of tabletop exercise or live incident with after-action report','IR tool inventory (ticketing system, forensic tools, communication plan)','Documented IR team roles and contact information']},
      { id:'3.6.2', pts:3, title:'Incident Tracking and Reporting',
        text:'Track, document, and report incidents to designated officials and/or authorities both internal and external to the organization.',
        explanation:'Every security incident must be tracked with complete documentation and reported to appropriate authorities. For CUI incidents, DFARS 252.204-7012 requires reporting to the DoD via DIBNET (dibnet.dod.mil) within 72 hours of discovery. An internal ticketing or incident log is required for tracking. Document all incidents, including near-misses.',
        evidence:['Incident log or ticketing system with historical incident records','Documented 72-hour <a href="https://dibnet.dod.mil" target="_blank" rel="noopener noreferrer">DIBNET</a> reporting procedure for CUI incidents (required by <a href="https://www.ecfr.gov/current/title-48/chapter-2/subchapter-A/part-252/subpart-252.2/section-252.204-7012" target="_blank" rel="noopener noreferrer">DFARS 252.204-7012</a>)','Internal escalation and reporting procedure identifying designated officials','Evidence of past incident reporting (redacted as needed) or confirmation of no reportable incidents']},
      { id:'3.6.3', pts:3, title:'Incident Response Testing',
        text:'Test the organizational incident response capability.',
        explanation:'The IR capability must be exercised periodically — at minimum an annual tabletop exercise. Untested response plans are theoretical. The exercise should simulate a realistic scenario (ransomware, CUI exfiltration, insider threat), document what went well and what didn\'t, and drive updates to the plan.',
        evidence:['Tabletop exercise records showing date, participants, scenario used','After-action report documenting findings and lessons learned','Updates made to the IR plan following the exercise','Policy defining IR testing frequency (annual at minimum)']}
    ],
    findings: [
      'IR plan exists as a document but has never been tested — no tabletop or exercise records on file',
      'No documented 72-hour DIBNET reporting procedure; personnel unaware of the external reporting obligation',
      'Incident log is ad-hoc or absent; past incidents not formally documented',
      'IR plan not reviewed or updated after incidents or annually'
    ]
  },

  ma: {
    name: 'Maintenance', section: '3.7', count: 6, readTime: '6 min',
    summary: 'Six requirements governing how system maintenance is performed, controlled, and documented — including strict controls on remote maintenance sessions and media used during maintenance.',
    intro: 'The Maintenance family addresses the security risks inherent in maintenance activities — trusted-insider access, vendor remote support, diagnostic media, and equipment removed for repair. Its most impactful requirement (3.7.5, 5 points) mandates MFA for all remote maintenance sessions over external networks, a requirement that catches many organizations that allow vendor support without MFA.',
    themes: ['Controlled Maintenance','Remote Maintenance','Maintenance Personnel','Diagnostic Media','CUI Sanitization'],
    requirements: [
      { id:'3.7.1', pts:3, title:'Controlled Maintenance',
        text:'Perform maintenance on organizational information systems.',
        explanation:'Maintenance activities on in-scope systems must be scheduled, performed in a controlled manner, and documented. Unscheduled or undocumented maintenance creates an untracked window during which system state is unknown. Maintenance windows should be authorized through the change management process.',
        evidence:['Maintenance policy defining requirements for scheduled and emergency maintenance','Maintenance log or change management records for recent maintenance activities','Maintenance windows visible in change management system','Evidence that maintenance activities are documented with what was done and by whom']},
      { id:'3.7.2', pts:3, title:'Maintenance Tool and Personnel Controls',
        text:'Provide controls on the tools, techniques, mechanisms, and personnel that conduct system maintenance.',
        explanation:'Maintenance tools — diagnostic software, remote support tools, admin utilities — must be authorized, tracked, and controlled. Maintenance personnel must have appropriate access for the specific work being performed, with access removed when maintenance is complete. Vendor access must be controlled and time-limited.',
        evidence:['Authorized maintenance tool list','Access management records for maintenance personnel (authorization before, removal after)','Vendor access logs showing time-limited sessions','Policy defining maintenance personnel controls and tool authorization requirements']},
      { id:'3.7.3', pts:3, title:'Equipment Sanitization for Maintenance',
        text:'Ensure equipment removed for maintenance is sanitized with respect to any CUI in storage.',
        explanation:'Before equipment containing CUI is removed from the facility for off-site maintenance (sending a laptop to a vendor, returning hardware to an OEM), the media must be sanitized per NIST 800-88, or CUI must be removed and protection verified. You cannot ship a storage device full of CUI to a repair depot.',
        evidence:['Media sanitization procedure referenced in maintenance process','Maintenance records showing sanitization step before equipment removal','Sanitization tool logs or certificates','Chain of custody documentation for equipment removed for maintenance']},
      { id:'3.7.4', pts:1, title:'Diagnostic Media Scanning',
        text:'Check media containing diagnostic and test programs for malicious code before the media are used in organizational systems.',
        explanation:'Any media (USB drives, optical disks) containing diagnostic or test software must be scanned for malware before being used on organizational systems. Supply chain attacks via maintenance media are a known attack vector — this requirement directly mitigates that risk.',
        evidence:['Policy requiring malware scan of all maintenance and diagnostic media before use','Antivirus/EDR scan logs for maintenance tools','Maintenance checklist including media scanning as a required step','Evidence of scan capability available to personnel performing maintenance']},
      { id:'3.7.5', pts:5, title:'MFA for Remote Maintenance',
        text:'Require multifactor authentication to establish nonlocal maintenance sessions via external network connections and terminate such connections when nonlocal maintenance is complete.',
        explanation:'Remote maintenance sessions — vendor support connections, remote administration over the internet — must use MFA when connecting via external networks. Password-only remote maintenance access is a critical, 5-point finding. The session must also be formally terminated when maintenance is complete, not left open indefinitely.',
        evidence:['Remote maintenance policy requiring MFA for all sessions over external networks','MFA configuration for remote access tools used by maintenance personnel (TeamViewer, ConnectWise, VPN)','Session termination procedure and logs showing sessions ended after maintenance','Vendor agreements specifying MFA requirements for remote support']},
      { id:'3.7.6', pts:3, title:'Maintenance Personnel Supervision',
        text:'Supervise the maintenance activities of personnel without required access authorization.',
        explanation:'When maintenance personnel — contractors, vendors, or others — lack the required security authorization or clearance for the environment, their activities must be supervised by an authorized individual. You cannot leave an uncleared vendor alone with your CUI systems. The escort must remain present for the duration of the maintenance.',
        evidence:['Policy defining supervision requirements based on access authorization levels','Maintenance visit records showing escort/supervision was provided','Identification of authorized escorts and their qualifications','Visitor log entries for maintenance personnel without access authorization']}
    ],
    findings: [
      'Remote vendor support sessions conducted without MFA — password-only access over external networks',
      'No controls on which remote support tools are authorized; vendors use their own tools without approval',
      'Equipment removed for repair without sanitization of CUI from storage',
      'Maintenance activities undocumented; no records of what was done or by whom',
      'Uncleared maintenance personnel left unsupervised in areas with CUI systems'
    ]
  },

  mp: {
    name: 'Media Protection', section: '3.8', count: 9, readTime: '8 min',
    summary: 'Nine requirements covering the protection, access control, marking, transport, sanitization, and destruction of media containing CUI — both digital and physical.',
    intro: 'Media Protection addresses the physical and logical handling of all media — hard drives, USB drives, backup tapes, optical media, and paper documents — containing CUI. Its requirements span the full media lifecycle from storage through transport, sanitization, and disposal. The 5-point requirements (3.8.2 and 3.8.6) target access control to CUI media and encryption during transport.',
    themes: ['Media Storage','Media Access Control','CUI Marking','Media Transport','Sanitization','Removable Media'],
    requirements: [
      { id:'3.8.1', pts:3, title:'Media Physical Protection',
        text:'Protect (physically control and securely store) information system media containing CUI, both paper and digital.',
        explanation:'Media containing CUI — hard drives, USB drives, backup tapes, printed documents — must be physically secured when not in active use. This means locked cabinets, controlled rooms, or other secure physical storage. Leaving CUI media unattended on a desk or in an unsecured drawer fails this requirement.',
        evidence:['Physical security policy for CUI media storage','Locked cabinet or secure storage room for CUI media','Media inventory with assigned storage locations','Physical inspection records confirming media is stored securely when not in use']},
      { id:'3.8.2', pts:5, title:'Media Access Control',
        text:'Limit access to CUI on information system media to authorized users.',
        explanation:'Access to CUI on media must be restricted to authorized individuals — not everyone with physical access to a server room or storage area. Implement both physical access controls (who can enter the storage area) and logical controls (encryption with key management) to limit who can actually read the CUI.',
        evidence:['Media access authorization list showing who is permitted access','Physical access logs to media storage areas','Encryption configuration for digital media (ensures only authorized users with keys can access CUI)','Policy defining media access authorization requirements and review frequency']},
      { id:'3.8.3', pts:3, title:'Media Sanitization',
        text:'Sanitize or destroy information system media before disposal or reuse.',
        explanation:'Before media is disposed of or reused in a different context, it must be sanitized using methods appropriate to the media type per NIST SP 800-88 Rev 1. Simply deleting files or formatting a drive is not sufficient — data recovery tools can recover "deleted" data. Use secure erase tools, degaussing, or physical destruction for drives with CUI.',
        evidence:['Media sanitization policy referencing <a href="https://csrc.nist.gov/publications/detail/sp/800-88/rev-1/final" target="_blank" rel="noopener noreferrer">NIST SP 800-88 Rev 1</a>','Sanitization tool logs or certificates of sanitization','Physical destruction certificates for media requiring destruction','Chain of custody records for media sent to third-party sanitization or destruction']},
      { id:'3.8.4', pts:3, title:'CUI Media Marking',
        text:'Mark media with necessary CUI markings and distribution limitations.',
        explanation:'Physical media containing CUI must be marked with the appropriate CUI designation and any applicable category markings and distribution limitations, per <a href="https://www.archives.gov/cui/registry/category-list" target="_blank" rel="noopener noreferrer">NARA CUI requirements</a>. Unmarked CUI media may be handled inappropriately by personnel who don\'t know it contains CUI. This applies to external drives, backup tapes, printouts, and other physical media.',
        evidence:['CUI marking policy aligned with <a href="https://www.archives.gov/cui/registry/category-list" target="_blank" rel="noopener noreferrer">NARA CUI Registry</a> requirements','Examples of properly marked CUI media and printouts','Training records confirming personnel understand marking requirements','Labeling supplies or templates available to personnel who handle CUI media']},
      { id:'3.8.5', pts:3, title:'Media Transport Accountability',
        text:'Control access to media containing CUI and maintain accountability for media during transport.',
        explanation:'When CUI media is physically transported — moved off-site, shipped to another facility, handed to a courier — access controls and chain of custody must be maintained during transit. Use locked containers or tamper-evident packaging, document chain of custody, and track media throughout transport.',
        evidence:['Media transport policy with chain of custody requirements','Transport log or chain of custody form for CUI media movements','Sealed/locked container or tamper-evident packaging for CUI media transport','Courier or shipping agreements specifying handling requirements for CUI media']},
      { id:'3.8.6', pts:5, title:'CUI Encryption During Transport',
        text:'Implement cryptographic mechanisms to protect the confidentiality of CUI during transport unless otherwise protected by alternative physical safeguards.',
        explanation:'CUI transported on portable media must be encrypted using FIPS-validated cryptographic mechanisms. An unencrypted USB drive or laptop with CUI that is lost or stolen during transport is a reportable breach. BitLocker, VeraCrypt (when configured for FIPS mode), and hardware-encrypted drives are common implementations.',
        evidence:['Encryption solution documentation confirming FIPS 140-2 or 140-3 validation','BitLocker or equivalent encryption configuration on laptops and portable drives','Policy requiring encryption for all CUI media transport','FIPS validation certificate number for the encryption module in use']},
      { id:'3.8.7', pts:1, title:'Removable Media Controls',
        text:'Control the use of removable media on information system components.',
        explanation:'The organization must control which removable media can be used with organizational systems. This means an approved media list, technical enforcement (e.g., blocking unauthorized USB devices via endpoint management), or both. Uncontrolled USB use enables both data exfiltration and malware introduction.',
        evidence:['Policy defining removable media controls and approved use cases','Endpoint management or Group Policy configuration restricting unauthorized USB devices','Authorized removable media inventory with assigned identifiers','Exceptions documentation for approved portable storage devices']},
      { id:'3.8.8', pts:1, title:'Unidentified Portable Storage Prohibition',
        text:'Prohibit the use of portable storage devices when such devices have no identifiable owner.',
        explanation:'Found USB drives, promotional giveaway drives, drives with no clear owner or organizational tracking must not be used on organizational systems. This directly addresses "USB baiting" attacks where attackers leave infected drives in parking lots or common areas. Technical controls that block unauthorized USB devices are the most reliable implementation.',
        evidence:['Policy prohibiting use of portable storage with no identifiable owner','Security awareness training records covering USB baiting attacks','Technical controls (endpoint management) blocking unauthorized/unregistered USB devices','Authorized device registry confirming which devices are permitted']},
      { id:'3.8.9', pts:3, title:'Backup CUI Confidentiality',
        text:'Protect the confidentiality of backup CUI at storage locations.',
        explanation:'CUI stored in backups must receive the same confidentiality protection as CUI in primary storage. Offsite backup tapes sitting unencrypted on a shelf at a colocation facility are a critical finding. Apply encryption to backup media, secure the backup storage location, and verify protection periodically.',
        evidence:['Backup storage encryption configuration','Offsite storage agreement with documented security requirements','Physical security controls at backup storage location (locked room, access controls)','Periodic review records confirming backup media protection']}
    ],
    findings: [
      'Backup tapes or portable drives stored at offsite facilities without encryption or physical security verification',
      'No sanitization process for retired hard drives — drives disposed of without secure erase or physical destruction',
      'CUI media (printouts, external drives) not marked with required CUI designations',
      'USB devices uncontrolled — any USB drive can be connected to organizational systems',
      'No chain of custody maintained when CUI media is transported off-site'
    ]
  },

  ps: {
    name: 'Personnel Security', section: '3.9', count: 2, readTime: '4 min',
    summary: 'Two requirements covering pre-employment screening for personnel with system access and protecting CUI during and after personnel actions such as terminations and transfers.',
    intro: 'Personnel Security addresses the human factor in CUI protection — who is hired into positions with system access, and what happens when they leave or change roles. Despite having only 2 requirements, the second (3.9.2, 5 points) is a critical finding if your offboarding process fails to immediately terminate system access for departing personnel.',
    themes: ['Background Screening','Termination Procedures','Transfer Procedures','Access Revocation'],
    requirements: [
      { id:'3.9.1', pts:3, title:'Personnel Screening',
        text:'Screen individuals prior to authorizing access to organizational systems containing CUI.',
        explanation:'Individuals must be screened before being granted access to systems containing CUI. The screening must be commensurate with the risk of the position — background checks are the standard implementation. This requirement applies to employees, contractors, and subcontractors who will have access to CUI systems.',
        evidence:['Background check policy defining scope and requirements by position type','Background check completion records tied to access authorization','Contractor screening requirements included in contract language','Evidence that access is not granted until screening is complete']},
      { id:'3.9.2', pts:5, title:'Personnel Action Procedures',
        text:'Ensure that CUI is protected during and after personnel actions such as terminations and transfers.',
        explanation:'When employees terminate or transfer, access to CUI must be protected throughout the process. This means immediate account disabling at termination (same day, not end of week), recovery of CUI-bearing devices and media, and revoking physical access. The offboarding process must be documented, consistently executed, and verified.',
        evidence:['Termination and transfer checklist covering all CUI access revocation steps','IT offboarding procedure with defined timelines for account disabling (e.g., same day as termination)','Account audit records showing terminated employee accounts were promptly disabled','Records of device and media recovery from departing personnel']}
    ],
    findings: [
      'Terminated employees\' accounts not disabled for days or weeks after departure',
      'No documented offboarding procedure tying HR termination to IT access revocation',
      'Contractor access not included in screening requirements or access revocation process',
      'CUI-bearing devices (laptops, mobile devices) not recovered at termination'
    ]
  },

  pe: {
    name: 'Physical Protection', section: '3.10', count: 6, readTime: '6 min',
    summary: 'Six requirements governing physical access to systems and facilities, visitor management, physical access logging, and safeguarding CUI at alternate work sites.',
    intro: 'Physical Protection establishes controls over who can physically access systems, equipment, and the environments where CUI is processed. Its 6 requirements cover access control to facilities, monitoring, visitor management, physical access logging, and the increasingly important requirement to safeguard CUI at alternate work sites (home offices, remote locations).',
    themes: ['Physical Access Control','Facility Monitoring','Visitor Management','Physical Access Logging','Alternate Work Sites'],
    requirements: [
      { id:'3.10.1', pts:3, title:'Physical Access Limitations',
        text:'Limit physical access to organizational systems, equipment, and the respective operating environments to authorized individuals.',
        explanation:'Physical access to server rooms, network closets, wiring areas, and other locations where CUI systems are located must be restricted to personnel with an authorized need. Implement physical access controls — keycards, PIN-based locks, biometrics — and maintain records of who is authorized. Physical security and logical security are interdependent.',
        evidence:['Physical access control system (badge reader, key management) records','Authorized personnel list for sensitive physical areas','Physical access policy defining who requires access and how it is granted','Evidence that physical access authorization is reviewed periodically']},
      { id:'3.10.2', pts:3, title:'Facility and Infrastructure Monitoring',
        text:'Protect and monitor the physical facility and support infrastructure for those systems.',
        explanation:'The physical facility and supporting infrastructure — power systems, HVAC, cabling, network equipment locations — must be actively monitored and protected. Physical security monitoring (CCTV, intrusion alarms, environmental sensors) provides the detection capability to identify physical security incidents.',
        evidence:['Physical security monitoring system (CCTV, intrusion alarm) configuration and coverage map','Environmental monitoring for server rooms (temperature, humidity, water detection)','Alarm response procedure defining how physical security events are handled','Security guard logs or monitoring service records if applicable']},
      { id:'3.10.3', pts:1, title:'Visitor Escorting',
        text:'Escort visitors and monitor visitor activity.',
        explanation:'Visitors to areas containing CUI systems must be escorted at all times by an authorized individual. Unescorted vendor access to server rooms or work areas where CUI is processed is a finding. Visitor logs must be maintained at all controlled entry points.',
        evidence:['Visitor policy requiring escort at all times in controlled areas','Visitor log records for controlled access areas','Escort identification and authorization process','Physical signage indicating escort-required areas']},
      { id:'3.10.4', pts:1, title:'Physical Access Logging',
        text:'Maintain audit logs of physical access.',
        explanation:'Electronic badge reader logs, or manual visitor sign-in sheets for areas without badge systems, must be maintained. These physical access logs support investigation of security incidents and provide accountability for who was in sensitive areas. Retention period should align with your overall log retention policy.',
        evidence:['Electronic badge system access logs for controlled areas','Visitor log records at controlled entry points','Physical access log retention policy defining retention period','Evidence of periodic review of physical access logs for anomalies']},
      { id:'3.10.5', pts:1, title:'Physical Access Device Management',
        text:'Control and manage physical access devices.',
        explanation:'Physical access devices — key cards, physical keys, PINs, FOBs — must be managed across their lifecycle: issued to specific individuals, tracked in an inventory, and recovered when no longer needed. Lost or unreturned access devices must trigger a defined response (deactivation, re-keying). This prevents former employees\' credentials from remaining valid.',
        evidence:['Access device inventory showing issuance and current status','Issued device tracking system tied to active personnel list','Lost device reporting procedure and response protocol','Evidence that devices are deactivated when personnel depart']},
      { id:'3.10.6', pts:1, title:'Alternate Work Site Safeguards',
        text:'Enforce safeguarding measures for CUI at alternate work sites.',
        explanation:'Employees working remotely with CUI — home offices, hotel rooms, shared coworking spaces — must follow documented procedures for physically securing CUI. This requirement has become increasingly significant as remote work has become standard. A telework security policy covering physical CUI handling at alternate sites is required.',
        evidence:['Remote work or telework policy covering physical CUI safeguarding at alternate sites','Training records documenting personnel understand alternate site requirements','Telework agreement signed by employees acknowledging CUI handling obligations','Guidance for home office physical security (locking workstations, securing printed CUI)']}
    ],
    findings: [
      'Server rooms or network closets accessible without physical access controls (unlocked doors)',
      'Visitor log not maintained, or visitors allowed in controlled areas without escort',
      'No policy or training covering CUI physical protection at home offices and remote work locations',
      'Physical access devices not recovered at employee termination; former employee badges remain active'
    ]
  },

  ra: {
    name: 'Risk Assessment', section: '3.11', count: 3, readTime: '5 min',
    summary: 'Three 5-point requirements covering periodic organizational risk assessments, vulnerability scanning of systems and applications, and risk-based vulnerability remediation.',
    intro: 'Risk Assessment carries 15 weighted points across just 3 requirements — every one of them worth 5 points. These requirements establish the analytical foundation for security decision-making: you must formally assess organizational risk, actively scan for vulnerabilities, and remediate those vulnerabilities according to risk-based priorities. Failing all three costs 15 SPRS points.',
    themes: ['Risk Assessment','Vulnerability Scanning','Vulnerability Remediation','Risk-Based Prioritization'],
    requirements: [
      { id:'3.11.1', pts:5, title:'Periodic Risk Assessments',
        text:'Periodically assess the risk to organizational operations (including mission, functions, image, or reputation), assets, and individuals, resulting from the operation of organizational systems and the associated processing, storage, or transmission of CUI.',
        explanation:'The organization must conduct formal, documented risk assessments at defined intervals — annually at minimum, and whenever significant system changes occur. A risk assessment identifies threats, vulnerabilities, likelihood, impact, and countermeasures. It must be documented, dated, signed by a responsible official, and feed into remediation priorities.',
        evidence:['Risk assessment report (dated, within the past year)','Risk methodology or framework documentation','Risk register showing identified risks with likelihood, impact, and risk ratings','Evidence that risk assessment findings fed into security investment and remediation priorities']},
      { id:'3.11.2', pts:5, title:'Vulnerability Scanning',
        text:'Scan for vulnerabilities in organizational systems and applications periodically and when new vulnerabilities affecting those systems and applications are identified.',
        explanation:'Systems must be actively scanned for technical vulnerabilities on a defined schedule (at minimum quarterly, preferably monthly or continuously) and on an ad-hoc basis when significant new vulnerabilities are publicly disclosed. Authenticated scans provide significantly better coverage than unauthenticated scans. Scan results must be retained and fed into remediation tracking.',
        evidence:['Vulnerability scan reports (authenticated scans, within defined scan period)','Scanning tool configuration (Nessus, Qualys, Tenable, OpenVAS)','Scan schedule and frequency defined in policy','Evidence of ad-hoc scanning in response to significant CVE disclosures (e.g., Log4Shell, ProxyShell)']},
      { id:'3.11.3', pts:5, title:'Vulnerability Remediation',
        text:'Remediate vulnerabilities in accordance with risk assessments.',
        explanation:'Identified vulnerabilities must be remediated according to risk-based priorities with defined timelines. Critical vulnerabilities require faster remediation than informational findings. Remediation timelines should be defined in policy (e.g., Critical: 15 days, High: 30 days, Medium: 90 days) and compliance tracked against those SLAs.',
        evidence:['Vulnerability remediation policy with defined SLAs by severity level','POA&M entries for open vulnerabilities showing target dates and owners','Patch management reports showing vulnerability remediation completion','Closed vulnerability records demonstrating SLA compliance']}
    ],
    findings: [
      'No formal risk assessment conducted, or last assessment over a year old with no updates for significant changes',
      'Vulnerability scanning conducted only annually or not at all; unauthenticated scans used exclusively',
      'Vulnerability scan results not tracked for remediation; no defined remediation SLAs',
      'Critical vulnerabilities open for months without documented remediation plan or accepted risk decision'
    ]
  },

  ca: {
    name: 'Security Assessment', section: '3.12', count: 4, readTime: '6 min',
    summary: 'Four requirements covering periodic security control assessments, plans of action and milestones (POA&M), ongoing monitoring, and maintaining a system security plan (SSP).',
    intro: 'Security Assessment establishes the continuous management framework for your compliance posture. Its 4 requirements — three carrying 5-point weight — require you to periodically test that controls are actually working, maintain an active POA&M for deficiencies, monitor controls on an ongoing basis, and keep your System Security Plan current. The SSP (3.12.4) is the single most important document artifact in a CMMC assessment.',
    themes: ['Control Assessment','POA&M','Ongoing Monitoring','System Security Plan (SSP)'],
    requirements: [
      { id:'3.12.1', pts:5, title:'Security Control Assessment',
        text:'Periodically assess the security controls in organizational systems to determine if the controls are effective in their application.',
        explanation:'Security controls must be assessed periodically to verify they are actually working — not just documented. This means testing controls: can users actually reach systems they shouldn\'t? Does the account lockout policy actually trigger? Are logs actually being generated and retained? Annual control assessments, with results documented, are the standard.',
        evidence:['Security assessment plan and scope document','Assessment report documenting which controls were tested and results','Testing methodology documentation (interviews, document review, technical testing)','Evidence of follow-up actions for controls that failed assessment testing']},
      { id:'3.12.2', pts:5, title:'Plans of Action and Milestones (POA&M)',
        text:'Develop and implement plans of action designed to correct deficiencies and reduce or eliminate vulnerabilities in organizational systems.',
        explanation:'Every identified security deficiency — whether from a risk assessment, vulnerability scan, internal audit, or assessment — must have a documented remediation plan: assigned owner, milestones, resources required, and target completion date. The POA&M is a living document that must be actively maintained and updated as items are completed or timelines change.',
        evidence:['Current POA&M document covering all known deficiencies','Regular POA&M update records showing the document is actively maintained','Completed POA&M items with closure evidence and dates','Senior official review records showing POA&M is reviewed at defined intervals']},
      { id:'3.12.3', pts:3, title:'Ongoing Security Control Monitoring',
        text:'Monitor information system security controls on an ongoing basis to ensure the continued effectiveness of the controls.',
        explanation:'Security controls must be monitored continuously between formal assessments — not just checked annually. Automated monitoring tools, regular log review, vulnerability scanning, and configuration compliance checking all contribute to ongoing monitoring. The organization must have a process to detect when controls degrade or are disabled.',
        evidence:['SIEM or monitoring tool configuration showing continuous control monitoring','Regular log review records (weekly or daily)','Automated configuration compliance scanning (ensuring systems remain at baseline)','Evidence of monitoring activity between formal assessments (dashboards, reports, alerts)']},
      { id:'3.12.4', pts:5, title:'System Security Plan (SSP)',
        text:'Develop, document, and periodically update system security plans that describe system boundaries, system environments of operation, how security requirements are implemented, and the relationships with or connections to other systems.',
        explanation:'The SSP is the cornerstone document of your CMMC compliance posture. It must describe the authorization boundary, operating environment, how each of the 110 NIST SP 800-171 requirements is implemented (or why it is not applicable), and connections to other systems. It must be current, complete, reviewed at least annually, and signed by a senior official.',
        evidence:['Complete SSP document addressing all 110 requirements with implementation status','System boundary diagram and network architecture diagram included in or appended to SSP','Connection to other systems documented (system interconnections, cloud services)','Evidence of annual review (dated revision) and senior official signature']}
    ],
    findings: [
      'SSP is incomplete — significant sections not addressed, or implementation descriptions are generic rather than system-specific',
      'POA&M not maintained; identified deficiencies have no remediation plan or owner assigned',
      'Security control assessment is policy-only — no evidence that controls were actually tested',
      'SSP not updated when system architecture changed; document does not reflect current environment'
    ]
  },

  sc: {
    name: 'System and Communications Protection', section: '3.13', count: 16, readTime: '12 min',
    summary: 'Sixteen requirements covering network boundary protection, CUI encryption in transit and at rest, network segmentation, FIPS-validated cryptography, and session security.',
    intro: 'System and Communications Protection is the second-largest family, with 16 requirements addressing how data in motion and at rest is protected, how network boundaries are enforced, and how communications integrity and confidentiality are maintained. Four requirements carry 5-point weight — including CUI encryption in transit (3.13.8), CUI encryption at rest (3.13.16), FIPS-validated cryptography (3.13.11), and boundary monitoring (3.13.1).',
    themes: ['Boundary Protection','CUI Encryption','Network Segmentation','FIPS Cryptography','Key Management','Session Security'],
    requirements: [
      { id:'3.13.1', pts:5, title:'Communication Boundary Monitoring',
        text:'Monitor, control, and protect organizational communications (information transmitted or received by organizational systems) at the external boundaries and key internal boundaries of the systems.',
        explanation:'Communications at external boundaries (internet perimeter) and key internal boundaries (CUI segment boundaries, DMZ perimeters) must be monitored, controlled, and protected. This requires firewalls at boundaries, IDS/IPS capability, and logging of traffic at key points. "Monitor" means actively reviewed, not just logged.',
        evidence:['Firewall configuration and rules at external and key internal boundaries','Network diagram showing boundary controls and monitoring points','IDS/IPS deployment and alert configuration','Traffic monitoring capability (NetFlow, SIEM) showing boundary visibility']},
      { id:'3.13.2', pts:3, title:'Security-Oriented Architecture',
        text:'Employ architectural designs, software development techniques, and systems engineering principles that promote effective information security within organizational systems.',
        explanation:'System design must incorporate security principles — defense in depth, least privilege at the architecture level, secure design patterns, and security requirements integrated from the start rather than bolted on. Assessors evaluate this through architecture documentation and design decision records.',
        evidence:['System architecture documentation showing security design principles applied','Security architecture review records for significant system changes','Secure SDLC policy if the organization develops software','Evidence of security considerations in architectural decisions (network diagrams, design documents)']},
      { id:'3.13.3', pts:1, title:'Functionality Separation',
        text:'Separate user functionality from information system management functionality.',
        explanation:'Administrative management interfaces must be separated from regular user-facing functionality — through separate networks (management VLAN), separate management interfaces, jump servers, or dedicated admin workstations. Admins should not manage production systems from the same workstation and account they use for everyday tasks.',
        evidence:['Network diagram showing management plane separation (management VLAN or OOB network)','Jump server or Privileged Access Workstation (PAW) configuration','Policy requiring separate workstations or management interfaces for admin activities','Evidence that management interfaces are not accessible from user workstations']},
      { id:'3.13.4', pts:1, title:'Shared Resource Information Transfer Prevention',
        text:'Prevent unauthorized and unintended information transfer via shared system resources.',
        explanation:'Shared system resources — memory, caches, storage — must not enable unauthorized data transfer between processes or users. This is typically addressed through OS hardening (enabling memory protection features), hypervisor security controls for virtualized environments, and process isolation. Modern OS defaults often satisfy this with proper hardening.',
        evidence:['OS hardening configuration showing memory protection features enabled (ASLR, DEP/NX)','Hypervisor security settings ensuring VM isolation','System hardening documentation addressing shared resource controls','Security baseline configuration evidence']},
      { id:'3.13.5', pts:3, title:'Public Component Network Separation',
        text:'Implement subnetworks for publicly accessible system components that are physically or logically separated from internal networks.',
        explanation:'Public-facing components — web servers, public APIs, email gateways, DNS servers — must reside in a separate network segment (DMZ) that is logically or physically isolated from internal networks containing CUI. A web server in the same flat network as CUI workstations is a critical architectural finding.',
        evidence:['Network diagram showing DMZ architecture with publicly accessible systems isolated','Firewall rules enforcing separation between DMZ and internal CUI network','Evidence that public-facing systems cannot directly access CUI systems','Technical verification that DMZ-to-internal access is controlled and logged']},
      { id:'3.13.6', pts:3, title:'Default-Deny Network Policy',
        text:'Deny network communications traffic by default and allow network communications traffic by exception (deny all, permit by exception).',
        explanation:'Firewall and network access control policy must be "deny all, permit by exception" — not the reverse. Default-allow rules with specific denies are insufficient. Build an explicit allowlist of required traffic flows and block everything else. This should be enforced at perimeter firewalls and key internal boundaries.',
        evidence:['Firewall rule configuration showing implicit or explicit deny-all rule at the bottom','Network traffic allowlist documenting all permitted flows with business justification','Evidence that firewall rules are reviewed and minimized periodically','Policy statement requiring default-deny as the baseline network posture']},
      { id:'3.13.7', pts:1, title:'Split Tunneling Prevention',
        text:'Prevent remote devices from simultaneously connecting to the system and to resources in other domains (i.e., split tunneling).',
        explanation:'When users are connected via VPN, all network traffic must route through the VPN — not split between the VPN and direct internet connections. Split tunneling allows simultaneous access to both the corporate network and the internet, enabling an attacker on the same internet path to pivot to the corporate network.',
        evidence:['VPN configuration showing split tunneling disabled (or equivalent policy enforcement)','Technical test demonstrating that VPN-connected devices route all traffic through the tunnel','VPN policy document specifying prohibition on split tunneling','Monitoring capability to detect VPN misconfigurations']},
      { id:'3.13.8', pts:5, title:'CUI Encryption in Transit',
        text:'Implement cryptographic mechanisms to prevent unauthorized disclosure of CUI during transmission unless otherwise protected by alternative physical safeguards.',
        explanation:'CUI must be encrypted during transmission using FIPS-validated mechanisms. This applies to all channels — email, file transfer, API communications, web applications, internal network transfers. Unencrypted transmission of CUI across any network path is a critical finding. Verify cipher suite strength, not just that TLS is in use.',
        evidence:['TLS configuration for all web applications and APIs handling CUI (TLS 1.2+, strong ciphers)','Email encryption configuration for CUI email transmission','FIPS-validated encryption module documentation for all CUI transmission channels','Scan results confirming no weak protocols or cipher suites in use for CUI paths']},
      { id:'3.13.9', pts:1, title:'Network Connection Termination',
        text:'Terminate network connections associated with communications sessions at the end of the sessions or after a defined period of inactivity.',
        explanation:'Network connections must be terminated when sessions end or after a defined inactivity period — preventing orphaned connections that could be hijacked. Configure idle timeouts on VPN sessions, remote desktop sessions, administrative interfaces, and network devices.',
        evidence:['VPN idle timeout configuration showing automatic session termination','Web application and administrative interface session timeout settings','Network device timeout configuration','Policy defining maximum idle period for network connections by connection type']},
      { id:'3.13.10', pts:3, title:'Cryptographic Key Management',
        text:'Establish and manage cryptographic keys for cryptography employed in organizational systems.',
        explanation:'Encryption is only as strong as its key management. Cryptographic keys must be generated securely, protected from unauthorized access, rotated on a defined schedule, and revoked when compromised. A key management policy and documented procedures for the full key lifecycle are required.',
        evidence:['Key management policy covering generation, storage, distribution, rotation, and revocation','Key inventory documenting key types, locations, and rotation schedules','Secure key storage mechanism (HSM, dedicated secrets management tool)','Key rotation records demonstrating compliance with defined schedule']},
      { id:'3.13.11', pts:5, title:'FIPS-Validated Cryptography',
        text:'Employ FIPS-validated cryptography when used to protect the confidentiality of CUI.',
        explanation:'When cryptography is used to protect CUI confidentiality, the cryptographic modules must be FIPS 140-2 or 140-3 validated — not just algorithmically equivalent. "We use AES-256" is not sufficient without FIPS validation. Enable FIPS mode on Windows (via Group Policy), use FIPS-validated TLS libraries, or deploy hardware with NIST CMVP certificates.',
        evidence:['<a href="https://csrc.nist.gov/projects/cryptographic-module-validation-program/validated-modules/search" target="_blank" rel="noopener noreferrer">NIST CMVP validated module certificate</a> for each cryptographic module protecting CUI','Windows FIPS mode configuration (Group Policy: System cryptography: Use FIPS-compliant algorithms)','TLS library or implementation FIPS validation documentation','Policy requiring FIPS-validated modules for all CUI confidentiality protection']},
      { id:'3.13.12', pts:1, title:'Collaborative Computing Device Controls',
        text:'Prohibit remote activation of collaborative computing devices and provide indication of use to present and remote users.',
        explanation:'Remote activation of cameras, microphones, and collaboration devices must be prohibited. Users should have visual or audio indication when these devices are active. This prevents unauthorized surveillance in areas where CUI is discussed. MDM configuration, endpoint management, and hardware indicator lights address this.',
        evidence:['MDM or endpoint management configuration disabling remote camera/microphone activation','Indicator light availability on deployed collaboration devices','Policy prohibiting remote activation of cameras and microphones on organizational devices','User training records covering proper handling of collaboration devices in CUI work areas']},
      { id:'3.13.13', pts:1, title:'Mobile Code Control',
        text:'Control and monitor the use of mobile code.',
        explanation:'Mobile code — scripts and executable content delivered via web browsers and other network mechanisms — must be controlled to prevent execution of malicious code from untrusted sources. Browser security configuration, web content filtering, and script-blocking tools address this. Define acceptable mobile code technologies and restrict others.',
        evidence:['Browser security configuration policy restricting untrusted mobile code execution','Web content filtering or proxy configuration controlling mobile code sources','Mobile code policy defining acceptable technologies (e.g., JavaScript from approved domains only)','Endpoint protection capable of detecting malicious mobile code']},
      { id:'3.13.14', pts:1, title:'VoIP Controls',
        text:'Control and monitor the use of Voice over Internet Protocol (VoIP) technologies.',
        explanation:'VoIP systems introduce security risks — potential eavesdropping, call interception, and network disruption. VoIP traffic must be managed on separate network segments, administrative access controlled, and traffic monitored. This applies to both dedicated VoIP systems and collaboration platforms (Teams, Zoom, WebEx) used for voice.',
        evidence:['VoIP or collaboration platform security policy','Network segmentation of VoIP traffic (separate VLAN from CUI data network)','VoIP system administrative access controls','Security configuration for voice collaboration platforms (encryption, authentication settings)']},
      { id:'3.13.15', pts:3, title:'Communications Session Authenticity',
        text:'Protect the authenticity of communications sessions.',
        explanation:'Communications sessions must be protected against session hijacking and man-in-the-middle attacks. Use protocols with session binding and message authentication — TLS with certificate validation, authenticated session tokens, anti-CSRF controls in web applications. Unauthenticated or weakly authenticated session protocols are a finding.',
        evidence:['TLS certificate configuration confirming proper validation and pinning where applicable','Session management implementation for web applications (secure, HttpOnly cookies)','Anti-CSRF protection in web applications processing CUI','Policy requiring authenticated session protocols for all CUI transmission']},
      { id:'3.13.16', pts:5, title:'CUI Encryption at Rest',
        text:'Protect the confidentiality of CUI at rest.',
        explanation:'CUI stored in systems — on hard drives, in databases, in file shares, in cloud storage — must be encrypted at rest using FIPS-validated mechanisms. This is the "encryption at rest" requirement. Full-disk encryption for endpoints and servers, database TDE, and cloud-native encryption (with organization-controlled keys where possible) are the standard implementations.',
        evidence:['Full-disk encryption deployment (BitLocker, FileVault) with FIPS mode enabled','Database encryption configuration (TDE or column-level encryption for CUI data)','Cloud storage encryption configuration with appropriate key control','MDM or endpoint management compliance report confirming encryption on all CUI-handling systems']}
    ],
    findings: [
      'CUI transmitted without encryption — HTTP instead of HTTPS, unencrypted file shares, email without encryption',
      'CUI stored in unencrypted databases or file shares, or full-disk encryption not deployed on all CUI-handling endpoints',
      'Non-FIPS-validated cryptography in use for CUI protection (custom implementations, non-validated TLS libraries)',
      'Flat network architecture with no separation between public-facing systems and CUI network',
      'Firewall rules are default-allow with specific denies rather than default-deny with explicit permits',
      'Split tunneling enabled on VPN, allowing simultaneous access to corporate and internet resources',
      'Cryptographic keys not managed — no rotation schedule, stored in configuration files, or shared across systems'
    ]
  },

  si: {
    name: 'System and Information Integrity', section: '3.14', count: 7, readTime: '7 min',
    summary: 'Seven requirements covering patch management, malware protection, security alerting, vulnerability scanning of running systems, and detecting unauthorized system use.',
    intro: 'System and Information Integrity addresses the operational security hygiene that prevents and detects attacks. Five of its seven requirements carry 5-point weight, making it one of the highest-impact families for SPRS scoring. Requirements span timely flaw remediation (patching), layered malware protection, security alert monitoring, and the ability to detect unauthorized use of organizational systems.',
    themes: ['Patch Management','Malware Protection','Security Alerting','Anomaly Detection','Intrusion Detection'],
    requirements: [
      { id:'3.14.1', pts:5, title:'Flaw Remediation',
        text:'Identify, report, and correct information and information system flaws in a timely manner.',
        explanation:'Security vulnerabilities and system flaws must be identified, documented, and corrected on a defined schedule based on risk. This is the patch management requirement. Define remediation SLAs by severity (e.g., Critical: 15 days, High: 30 days, Medium: 90 days) and track compliance against them. Unpatched critical vulnerabilities months after release are a significant finding.',
        evidence:['Patch management policy with defined remediation timelines by severity','Patch compliance reports from SCCM, Intune, WSUS, or equivalent','Vulnerability scan results showing patch status','POA&M entries for accepted-risk items with risk acceptance documentation']},
      { id:'3.14.2', pts:5, title:'Malware Protection',
        text:'Provide protection from malicious code at appropriate locations within organizational systems.',
        explanation:'Anti-malware protection must be deployed at appropriate locations throughout the environment — not just on user workstations. This includes servers, email gateways, web proxies, and network-level detection. Coverage gaps (unprotected servers, disabled agents) are findings. Consider the full threat vector map when determining "appropriate locations."',
        evidence:['Endpoint protection deployment report showing coverage across all in-scope systems','Email security gateway configuration showing attachment and link scanning','Web content filtering or proxy showing malware blocking','Network-level malware detection (IDS/IPS with malware signatures) if applicable']},
      { id:'3.14.3', pts:3, title:'Security Alerts and Advisories',
        text:'Monitor system security alerts and advisories and take appropriate actions in response.',
        explanation:'The organization must monitor security alerts and advisories from authoritative sources — CISA (us-cert.cisa.gov), NIST NVD, vendor security bulletins — and take documented action when relevant vulnerabilities or threats are identified. Subscribe to relevant feeds and document your review and response process.',
        evidence:['Security alert subscriptions: <a href="https://www.cisa.gov/news-events/cybersecurity-advisories" target="_blank" rel="noopener noreferrer">CISA Cybersecurity Advisories</a>, <a href="https://nvd.nist.gov/" target="_blank" rel="noopener noreferrer">NIST NVD</a>, and vendor security bulletins','Alert review procedure defining who reviews alerts, how frequently, and escalation path','Evidence of response to significant recent advisories (CISA KEV catalog entries affecting your systems)','Response tracking records tying alerts to remediation or risk acceptance decisions']},
      { id:'3.14.4', pts:5, title:'Malware Protection Updates',
        text:'Update malicious code protection mechanisms when new releases are available.',
        explanation:'Anti-malware definitions, signatures, and engines must be kept current. Auto-update should be enabled and verified. Signatures that are days or weeks old significantly degrade protection. Document your update mechanism, update frequency, and how you verify signatures are current across all endpoints.',
        evidence:['Endpoint protection auto-update configuration showing update source and frequency','Signature currency report from endpoint management console','Policy defining maximum allowable signature age','Alert configuration for endpoint protection failures or outdated signature notifications']},
      { id:'3.14.5', pts:3, title:'Malware Scanning',
        text:'Perform periodic scans of the information system and real-time scans of files from external sources as files are downloaded, opened, or executed.',
        explanation:'Two distinct scanning modes are required: (1) periodic full scans of all systems, and (2) real-time scanning that activates when files from external sources are downloaded, opened, or executed. Real-time scanning must cover email attachments, web downloads, and files copied from removable media. Periodic scans should cover all systems including servers.',
        evidence:['Endpoint protection configuration showing real-time scanning enabled','Periodic full scan schedule and recent scan results','Server-side antivirus configuration showing scheduled scans','Evidence that real-time scanning covers email and web sources']},
      { id:'3.14.6', pts:5, title:'Security Monitoring for Attacks',
        text:'Monitor organizational systems including inbound and outbound communications traffic, to detect attacks and indicators of potential attacks.',
        explanation:'Systems must be actively monitored for attacks and indicators of potential attacks — including analysis of both inbound and outbound traffic. Passive logging is insufficient; the organization needs detection capability. A SIEM with behavioral analytics, IDS/IPS, and EDR with threat intelligence are the standard implementation stack for this requirement.',
        evidence:['SIEM configuration showing inbound and outbound traffic analysis with alert rules','IDS/IPS deployment and alert history showing active detections','EDR solution with behavioral analytics and threat intelligence integration','Documented evidence of monitoring activity (reviewed alerts, investigated incidents, dashboards)']},
      { id:'3.14.7', pts:5, title:'Unauthorized System Use Detection',
        text:'Identify unauthorized use of organizational systems.',
        explanation:'The organization must be able to distinguish authorized activity from unauthorized use — detecting anomalous behavior, access outside normal patterns, or activity inconsistent with a user\'s role. User and Entity Behavior Analytics (UEBA), privileged account monitoring, and baseline anomaly detection all contribute to this capability.',
        evidence:['UEBA or behavioral analytics configuration with baseline profiles','Privileged account monitoring showing alerts for unusual privileged access','Anomaly detection rules in SIEM (off-hours access, geographic anomalies, data volume)',  'Evidence of past detections or investigations triggered by anomaly detection']}
    ],
    findings: [
      'Critical and high severity patches more than 30 days old on in-scope systems',
      'Endpoint protection not deployed on servers — coverage gap for the most targeted systems',
      'Malware signatures outdated; auto-update not configured or not verified as functioning',
      'No security monitoring beyond endpoint AV — no SIEM, IDS, or behavioral analytics in place',
      'Security alerts from CISA and vendors reviewed ad-hoc or not at all; no documented response process'
    ]
  }

};
